12	interface UseFindingGroupResourceStateOptions {
13	  group: FindingGroupRow;
14	  filters: Record<string, string>;
15	  hasHistoricalData: boolean;
16	  onResourceSelectionChange?: (findingIds: string[]) => void;
17	  scrollContainerRef?: React.RefObject<HTMLElement | null>;
18	}
19	
20	interface UseFindingGroupResourceStateReturn {
21	  rowSelection: RowSelectionState;
22	  resources: FindingResourceRow[];
23	  isLoading: boolean;
24	  sentinelRef: (node: HTMLDivElement | null) => void;
25	  refresh: () => void;
26	  loadMore: () => void;
27	  totalCount: number | null;
28	  drawer: ReturnType<typeof useResourceDetailDrawer>;
29	  handleDrawerMuteComplete: () => void;
30	  selectedFindingIds: string[];
31	  selectableRowCount: number;
32	  getRowCanSelect: (row: Row<FindingResourceRow>) => boolean;
33	  clearSelection: () => void;
34	  isSelected: (id: string) => boolean;
35	  handleMuteComplete: () => void;
36	  handleRowSelectionChange: OnChangeFn<RowSelectionState>;
37	  resolveSelectedFindingIds: (ids: string[]) => Promise<string[]>;
38	}
39	
40	export function useFindingGroupResourceState({
41	  group,
42	  filters,
43	  hasHistoricalData,
44	  onResourceSelectionChange,
45	  scrollContainerRef,
46	}: UseFindingGroupResourceStateOptions): UseFindingGroupResourceStateReturn {
47	  const [rowSelection, setRowSelection] = useState<RowSelectionState>({});
48	  const [resources, setResources] = useState<FindingResourceRow[]>([]);
49	  const [isLoading, setIsLoading] = useState(true);
50	
51	  const handleSetResources = (
52	    newResources: FindingResourceRow[],
53	    _hasMore: boolean,
54	  ) => {
55	    setResources(newResources);
56	    setIsLoading(false);
57	  };
58	
59	  const handleAppendResources = (
60	    newResources: FindingResourceRow[],
61	    _hasMore: boolean,
62	  ) => {
63	    setResources((prev) => [...prev, ...newResources]);
64	    setIsLoading(false);
65	  };
66	
67	  const handleSetLoading = (loading: boolean) => {
68	    setIsLoading(loading);
69	  };
70	
71	  const effectiveFilters = applyDefaultMutedFilter(filters);
72	
73	  const { sentinelRef, refresh, loadMore, totalCount } =
74	    useFindingGroupResources({
75	      checkId: group.checkId,
76	      hasDateOrScanFilter: hasHistoricalData,
77	      filters: effectiveFilters,
78	      onSetResources: handleSetResources,
79	      onAppendResources: handleAppendResources,
80	      onSetLoading: handleSetLoading,
81	      scrollContainerRef,
82	    });
83	
84	  const drawer = useResourceDetailDrawer({
85	    resources,
86	    totalResourceCount: totalCount ?? group.resourcesTotal,
87	    onRequestMoreResources: loadMore,
88	    canLoadOtherFindings: group.resourcesTotal !== 0,
89	    includeMutedInOtherFindings: true,
90	  });
91	
92	  const handleDrawerMuteComplete = () => {
93	    drawer.refetchCurrent();
94	    refresh();
95	  };
96	
97	  const selectedFindingIds = Object.keys(rowSelection)
98	    .filter((key) => rowSelection[key])
99	    .map((idx) => resources[parseInt(idx)]?.findingId)
100	    .filter((id): id is string => Boolean(id));
101	
102	  const selectableRowCount = resources.filter(canMuteFindingResource).length;
103	
104	  const getRowCanSelect = (row: Row<FindingResourceRow>): boolean => {
105	    return canMuteFindingResource(row.original);
106	  };
107	
108	  const clearSelection = () => {
109	    setRowSelection({});
110	    onResourceSelectionChange?.([]);
111	  };
112	
113	  const isSelected = (id: string) => {
114	    return selectedFindingIds.includes(id);
115	  };
116	
117	  const handleMuteComplete = () => {
118	    clearSelection();
119	    refresh();
120	  };
121	
122	  const handleRowSelectionChange = (
123	    updater:
124	      | RowSelectionState
125	      | ((prev: RowSelectionState) => RowSelectionState),
126	  ) => {
127	    const newSelection =
128	      typeof updater === "function" ? updater(rowSelection) : updater;
129	    setRowSelection(newSelection);
130	
131	    if (onResourceSelectionChange) {
132	      const newFindingIds = Object.keys(newSelection)
133	        .filter((key) => newSelection[key])
134	        .map((idx) => resources[parseInt(idx)]?.findingId)
135	        .filter((id): id is string => Boolean(id));
136	      onResourceSelectionChange(newFindingIds);
137	    }
138	  };
139	
140	  const resolveSelectedFindingIds = async (ids: string[]) => {
141	    return ids.filter(Boolean);
142	  };
143	
144	  return {
145	    rowSelection,
146	    resources,
147	    isLoading,
148	    sentinelRef,
149	    refresh,
150	    loadMore,
151	    totalCount,
152	    drawer,
153	    handleDrawerMuteComplete,
154	    selectedFindingIds,
155	    selectableRowCount,
156	    getRowCanSelect,
157	    clearSelection,
158	    isSelected,
159	    handleMuteComplete,
160	    handleRowSelectionChange,
161	    resolveSelectedFindingIds,
162	  };
163	}
