1	"use server";
2	
3	import { redirect } from "next/navigation";
4	
5	import { apiBaseUrl, getAuthHeaders } from "@/lib";
6	import { appendSanitizedProviderFilters } from "@/lib/provider-filters";
7	import { handleApiResponse } from "@/lib/server-actions-helper";
8	import { FilterParam } from "@/types/filters";
9	
10	/**
11	 * Maps filter[search] to filter[check_title__icontains] for finding-groups.
12	 * The finding-groups endpoint supports check_title__icontains for substring
13	 * matching on the human-readable check title displayed in the table.
14	 */
15	function mapSearchFilter(
16	  filters: Record<string, string | string[] | undefined>,
17	): Record<string, string | string[] | undefined> {
18	  const mapped = { ...filters };
19	  const searchValue = mapped["filter[search]"];
20	  if (searchValue) {
21	    mapped["filter[check_title__icontains]"] = searchValue;
22	    delete mapped["filter[search]"];
23	  }
24	  return mapped;
25	}
26	
27	function splitCsvFilterValues(value: string | string[] | undefined): string[] {
28	  if (Array.isArray(value)) {
29	    return value
30	      .flatMap((item) => item.split(","))
31	      .map((item) => item.trim())
32	      .filter(Boolean);
33	  }
34	
35	  if (typeof value === "string") {
36	    return value
37	      .split(",")
38	      .map((item) => item.trim())
39	      .filter(Boolean);
40	  }
41	
42	  return [];
43	}
44	
45	/**
46	 * Filters that belong to finding-groups but are NOT valid for the
47	 * finding-group resources sub-endpoint. These must be stripped before
48	 * calling the resources API to avoid empty results.
49	 */
50	const FINDING_GROUP_RESOURCE_UNSUPPORTED_FILTERS: FilterParam[] = [
51	  "filter[service__in]",
52	  "filter[scan__in]",
53	  "filter[scan_id]",
54	  "filter[scan_id__in]",
55	];
56	
57	function normalizeFindingGroupResourceFilters(
58	  filters: Record<string, string | string[] | undefined>,
59	): Record<string, string | string[] | undefined> {
60	  const normalized = Object.fromEntries(
61	    Object.entries(filters).filter(
62	      ([key]) =>
63	        !FINDING_GROUP_RESOURCE_UNSUPPORTED_FILTERS.includes(
64	          key as FilterParam,
65	        ),
