 * Shared sort tokens and presets for the findings surfaces.
 *
 * There are two distinct sort families because the two backends order their
 * columns differently:
 *
 * - Family A — plain findings. These are backed directly by Postgres ENUM
 *   columns whose natural ascending order already places FAIL before PASS and
 *   `critical` before `low`. Ascending order (no minus prefix) therefore puts
 *   the most important rows first, so `status`/`severity` tokens must NOT be
 *   minus-prefixed.
 *
 * - Family B — finding-groups. The grouped endpoint sorts on integer-weighted
 *   computed columns where a higher number means "more urgent" (more failing
 *   resources, higher severity, newer delta). Descending order (minus prefix)
 *   puts FAIL/critical/new results first, so `status`/`severity`/`delta`
 *   tokens must always be minus-prefixed.
 *
 * Keeping these in a dedicated, dependency-free module lets action and
 * component code import them via `@/lib` without pulling in server-only
 * authentication helpers.
 */

// ---------------------------------------------------------------------------
// Family A — plain findings (Postgres ENUM, ascending = FAIL/critical first)
// ---------------------------------------------------------------------------

/** Ascending status order surfaces FAIL before PASS. */
export const FINDINGS_FAIL_FIRST = "status";

/** Ascending severity order surfaces critical before low. */
export const FINDINGS_SEVERITY_HIGH_FIRST = "severity";

/** Most recently inserted findings first. */
export const FINDINGS_RECENT_INSERT = "-inserted_at";

/** Most recently updated findings first (latest-findings endpoint only). */
export const FINDINGS_RECENT_UPDATE = "-updated_at";

// ---------------------------------------------------------------------------
// Family B — finding-groups (integer-weighted columns, descending = first)
// ---------------------------------------------------------------------------

/** Descending status weight surfaces FAIL-heavy groups first. */
export const FG_FAIL_FIRST = "-status";

/** Descending severity weight surfaces critical-heavy groups first. */
export const FG_SEVERITY_HIGH_FIRST = "-severity";

/** Descending delta weight surfaces groups with new failing results first. */
export const FG_DELTA_NEW_FIRST = "-delta";

/** Most recently seen groups first. */
export const FG_RECENT_LAST_SEEN = "-last_seen_at";

// ---------------------------------------------------------------------------
// Composition helper
// ---------------------------------------------------------------------------

/**
 * Joins sort token strings into a single JSON:API `sort` parameter. The
 * leftmost token has the highest precedence. Returns an empty string when no
 * tokens are supplied.
 */
export function composeSort(...tokens: string[]): string {
  return tokens.join(",");
}

// ---------------------------------------------------------------------------
// Family A presets (plain findings)
// ---------------------------------------------------------------------------

/**
 * Default order for the plain findings list. No `delta` — plain findings do
 * not expose that field.
 */
export const FINDINGS_DEFAULT_SORT = composeSort(
  FINDINGS_FAIL_FIRST,
  FINDINGS_SEVERITY_HIGH_FIRST,
  FINDINGS_RECENT_INSERT,
);

/**
 * Order for findings lists that already apply a `filter[status]`; `status` is
 * omitted from the sort because every row shares the same status.
 */
export const FINDINGS_FILTERED_SORT = composeSort(
  FINDINGS_SEVERITY_HIGH_FIRST,
  FINDINGS_RECENT_INSERT,
);

/**
 * Order for the "other findings" list in the resource drawer, served by the
 * latest-findings endpoint which exposes `updated_at`.
 */
export const RESOURCE_DRAWER_OTHER_FINDINGS_SORT = composeSort(
  FINDINGS_SEVERITY_HIGH_FIRST,
  FINDINGS_RECENT_UPDATE,
);

// ---------------------------------------------------------------------------
// Family B presets (finding-groups)
// ---------------------------------------------------------------------------

/** Default order for the finding-groups list. */
export const FINDING_GROUPS_DEFAULT_SORT = composeSort(
  FG_FAIL_FIRST,
  FG_SEVERITY_HIGH_FIRST,
  FG_DELTA_NEW_FIRST,
  FG_RECENT_LAST_SEEN,
);

/** Default order for a finding-group's resources drill-down. */
export const FINDING_GROUP_RESOURCES_DEFAULT_SORT = composeSort(
  FG_FAIL_FIRST,
  FG_SEVERITY_HIGH_FIRST,
  FG_DELTA_NEW_FIRST,
  FG_RECENT_LAST_SEEN,
);

/**
 * Order for finding-groups lists that already apply a status filter. Omits
 * `status` and `delta`, and must NOT contain `inserted_at` — the grouped API
 * does not expose that field and rejects it with a backend error.
 */
export const FINDING_GROUPS_FILTERED_SORT = composeSort(
  FG_SEVERITY_HIGH_FIRST,
  FG_RECENT_LAST_SEEN,
);
