/**
 * Normalises a filter value into a flat array of non-empty, trimmed tokens.
 *
 * - `undefined` → `[]`
 * - a string is split on commas and each piece trimmed
 * - an array is flattened by splitting every element on commas
 * - tokens that are empty after trimming (stray/trailing commas) are dropped
 */
export function splitCsvFilterValues(
  value: string | string[] | undefined,
): string[] {
  if (Array.isArray(value)) {
    return value
      .flatMap((item) => item.split(","))
      .map((item) => item.trim())
      .filter(Boolean);
  }

  if (typeof value === "string") {
    return value
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean);
  }

  return [];
}

